import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"WAF — enumerated source for the Oracle on Azure IaaS workload assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/waf-oracle-iaas-workload-checklist.md","filePath":"frameworks/waf-oracle-iaas-workload-checklist.md"}'),d={name:"frameworks/waf-oracle-iaas-workload-checklist.md"};function s(i,t,n,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="waf-—-enumerated-source-for-the-oracle-on-azure-iaas-workload-assessment" tabindex="-1">WAF — enumerated source for the Oracle on Azure IaaS workload assessment <a class="header-anchor" href="#waf-—-enumerated-source-for-the-oracle-on-azure-iaas-workload-assessment" aria-label="Permalink to &quot;WAF — enumerated source for the Oracle on Azure IaaS workload assessment&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>This page enumerates the review that Microsoft publishes as <a href="https://learn.microsoft.com/en-us/assessments/d3acb4d8-8045-4635-9a31-0bcb3b10724a/" target="_blank" rel="noreferrer">Azure Well-Architected Oracle on Azure IaaS workload</a>, for Oracle software that the customer runs and manages on Azure virtual machines. <code>src/assess/rules/waf.oracle.yaml</code> is written against this page only, and every rule cites an item number from the tables below.</p><p>It is <strong>not</strong> <a href="https://learn.microsoft.com/azure/oracle/oracle-db/database-overview" target="_blank" rel="noreferrer">Oracle Database@Azure</a>, the OCI-managed Exadata service in Azure datacenters (<code>oracle.database/*</code> resources). That service has different resources and a different responsibility split, and is out of scope for this review.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/d3acb4d8-8045-4635-9a31-0bcb3b10724a/" target="_blank" rel="noreferrer">Azure Well-Architected Oracle on Azure IaaS workload</a> (30 minutes, multiple choice and multiple response; question text not published)</td></tr><tr><td>Framework version</td><td>Oracle on Azure virtual machines guidance on Microsoft Learn, current</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>Each source page below was fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25, except [SEC] and [APP], which were read only as search excerpts. Every ARM property an automated item reads (image reference, storage profile, network interface) was checked against the <code>Microsoft.Compute</code> and <code>Microsoft.Network</code> ARM template references. The properties were not exercised against a live Oracle estate.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>It is not Microsoft&#39;s question list.</strong> The assessment&#39;s questions are not published, and the Well-Architected Oracle IaaS workload pages (<code>well-architected/oracle-iaas/*</code>) now redirect to the Oracle on Azure product documentation. The items below are <strong>Scout&#39;s</strong> reading of the live Oracle-on-Azure-VM guidance, and the <code>WAF-ORA-*</code> IDs are Scout&#39;s. Where an item has no Oracle page behind it (WAF-ORA-CO-04, CO-05 and OE-01) it is Scout&#39;s application of the general Well-Architected pillar, and the table says so.</p><p>Sources:</p><ul><li>[OV] <a href="https://learn.microsoft.com/azure/virtual-machines/workloads/oracle/oracle-considerations" target="_blank" rel="noreferrer">Overview of Oracle applications and solutions on Azure</a></li><li>[REF] <a href="https://learn.microsoft.com/azure/virtual-machines/workloads/oracle/oracle-reference-architecture" target="_blank" rel="noreferrer">Architectures for Oracle database on Azure Virtual Machines</a></li><li>[BKP] <a href="https://learn.microsoft.com/azure/virtual-machines/workloads/oracle/oracle-database-backup-strategies" target="_blank" rel="noreferrer">Backup strategies for Oracle Database on an Azure Linux VM</a></li><li>[DES] <a href="https://learn.microsoft.com/azure/virtual-machines/workloads/oracle/oracle-design" target="_blank" rel="noreferrer">Architectures for Oracle Database Enterprise Edition on Azure</a></li><li>[PERF] <a href="https://learn.microsoft.com/azure/virtual-machines/workloads/oracle/oracle-performance-best-practice" target="_blank" rel="noreferrer">Performance best practices for Oracle on Azure VMs</a></li><li>[HUB] <a href="https://learn.microsoft.com/azure/well-architected/oracle-iaas/" target="_blank" rel="noreferrer">Oracle on Azure</a> (the page this URL now redirects to)</li><li>[SEC] <a href="https://learn.microsoft.com/azure/security/fundamentals/iaas" target="_blank" rel="noreferrer">Security best practices for IaaS workloads in Azure</a> (search excerpt only)</li><li>[APP] <a href="https://learn.microsoft.com/azure/virtual-machines/workloads/oracle/deploy-application-oracle-database-azure" target="_blank" rel="noreferrer">Architectures for Oracle applications with database on Azure Virtual Machines</a> (search excerpt only)</li></ul><h2 id="how-scout-recognises-an-oracle-vm" tabindex="-1">How Scout recognises an Oracle VM <a class="header-anchor" href="#how-scout-recognises-an-oracle-vm" aria-label="Permalink to &quot;How Scout recognises an Oracle VM&quot;">​</a></h2><p>ARM cannot say &quot;this VM runs an Oracle database&quot;. The only control-plane signal Scout reads is the <strong>Azure Marketplace image</strong>: a VM built from an image whose publisher is <code>Oracle</code> (Oracle Linux and Oracle Database images), taken from the universal discovery index (<code>$.discovery.Resources[*]</code>) at <code>Properties.storageProfile.imageReference.publisher</code>. No Oracle-specific projection exists yet.</p><ul><li>Automated items are <strong>gated</strong> on at least one such VM. An estate without one reports them Not assessed, never passed.</li><li>An Oracle database on Red Hat, another endorsed distribution or a custom image is <strong>invisible</strong> to the automated items, which then report Not assessed. The manual items stay answerable through the questionnaire.</li><li>An Oracle Linux VM that runs no Oracle software would still be scored; each automated remediation says the rule keys on the image.</li><li>Everything that depends on the database itself (Data Guard, RMAN, AWR sizing, licensing, ASM, Far Sync, Oracle Enterprise Manager) is manual by nature.</li></ul><h2 id="the-enumeration-—-34-items-across-the-five-pillars" tabindex="-1">The enumeration — 34 items across the five pillars <a class="header-anchor" href="#the-enumeration-—-34-items-across-the-five-pillars" aria-label="Permalink to &quot;The enumeration — 34 items across the five pillars&quot;">​</a></h2><h3 id="reliability-waf-ora-re-—-6-items" tabindex="-1">Reliability (WAF-ORA-RE) — 6 items <a class="header-anchor" href="#reliability-waf-ora-re-—-6-items" aria-label="Permalink to &quot;Reliability (WAF-ORA-RE) — 6 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-ORA-RE-01</td><td>Oracle VMs are deployed to availability zones in zone-capable regions</td><td>✅ Oracle-image VM → VM with no zone in a zone-capable region</td><td>REF, OV</td></tr><tr><td>WAF-ORA-RE-02</td><td>Database HA uses Data Guard or GoldenGate across separate zones, not RAC alone</td><td>❌ Manual — Oracle-image VMs attached</td><td>REF, OV</td></tr><tr><td>WAF-ORA-RE-03</td><td>A DR standby exists in another region, with Far Sync where zero data loss over distance is needed</td><td>❌ Manual</td><td>REF</td></tr><tr><td>WAF-ORA-RE-04</td><td>A backup strategy is in place and restores are tested</td><td>❌ Manual — protected items attached</td><td>BKP, OV</td></tr><tr><td>WAF-ORA-RE-05</td><td>Backups survive a regional outage</td><td>❌ Manual — recovery vaults attached</td><td>BKP</td></tr><tr><td>WAF-ORA-RE-06</td><td>The application tier uses cloud-native resilience patterns</td><td>❌ Manual</td><td>REF</td></tr></tbody></table><h3 id="security-waf-ora-se-—-7-items" tabindex="-1">Security (WAF-ORA-SE) — 7 items <a class="header-anchor" href="#security-waf-ora-se-—-7-items" aria-label="Permalink to &quot;Security (WAF-ORA-SE) — 7 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-ORA-SE-01</td><td>Oracle VMs have no public IP address</td><td>✅ Oracle-image VM → network interface with a public IP</td><td>DES</td></tr><tr><td>WAF-ORA-SE-02</td><td>Microsoft Defender for Servers is enabled</td><td>✅ Defender plan tier (per subscription)</td><td>SEC</td></tr><tr><td>WAF-ORA-SE-03</td><td>Oracle VMs are assessed for operating-system updates automatically</td><td>✅ Oracle-image VM → VM <code>assessmentMode</code></td><td>REF, SEC</td></tr><tr><td>WAF-ORA-SE-04</td><td>Administrators reach database VMs only through a bastion host or jumpbox</td><td>❌ Manual — internet-open NSG rules attached</td><td>DES, APP</td></tr><tr><td>WAF-ORA-SE-05</td><td>Application and database tiers sit in separate subnets under subnet-level NSG policy</td><td>❌ Manual</td><td>DES</td></tr><tr><td>WAF-ORA-SE-06</td><td>Data at rest and in transit is encrypted, including backup media</td><td>❌ Manual — disk encryption sets attached</td><td>DES, BKP, APP</td></tr><tr><td>WAF-ORA-SE-07</td><td>Azure RBAC gives each team the least privilege it needs</td><td>❌ Manual</td><td>APP</td></tr></tbody></table><h3 id="cost-optimization-waf-ora-co-—-5-items" tabindex="-1">Cost optimization (WAF-ORA-CO) — 5 items <a class="header-anchor" href="#cost-optimization-waf-ora-co-—-5-items" aria-label="Permalink to &quot;Cost optimization (WAF-ORA-CO) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-ORA-CO-01</td><td>VM size derives from AWR or Statspack and uses constrained vCPU sizes where core count drives licence cost</td><td>❌ Manual — Oracle-image VMs attached</td><td>OV, DES, REF</td></tr><tr><td>WAF-ORA-CO-02</td><td>Oracle licence entitlement matches the deployed vCPUs under bring-your-own-licence</td><td>❌ Manual</td><td>OV</td></tr><tr><td>WAF-ORA-CO-03</td><td>Storage choice balances price and performance, with lower tiers for development and test</td><td>❌ Manual</td><td>PERF</td></tr><tr><td>WAF-ORA-CO-04</td><td>Non-production Oracle VMs are deallocated when idle (Scout&#39;s application of the pillar)</td><td>❌ Manual</td><td>DES</td></tr><tr><td>WAF-ORA-CO-05</td><td>Steady production capacity is covered by reservations or savings plans (Scout&#39;s application of the pillar)</td><td>❌ Manual — reservations attached</td><td>—</td></tr></tbody></table><h3 id="operational-excellence-waf-ora-oe-—-8-items" tabindex="-1">Operational excellence (WAF-ORA-OE) — 8 items <a class="header-anchor" href="#operational-excellence-waf-ora-oe-—-8-items" aria-label="Permalink to &quot;Operational excellence (WAF-ORA-OE) — 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-ORA-OE-01</td><td>Oracle workloads are identifiable in Azure (Scout&#39;s addition, so reviews can scope them)</td><td>❌ Manual — VMs with Oracle-like names attached</td><td>—</td></tr><tr><td>WAF-ORA-OE-02</td><td>Azure Monitor with VM insights collects the disk metrics Oracle needs</td><td>❌ Manual — data collection rules attached</td><td>REF</td></tr><tr><td>WAF-ORA-OE-03</td><td>Oracle Enterprise Manager provides database-layer monitoring on its own VM</td><td>❌ Manual</td><td>REF, DES</td></tr><tr><td>WAF-ORA-OE-04</td><td>Alerts cover disk saturation and Service Health for the Oracle regions</td><td>❌ Manual — metric alert rules attached</td><td>REF</td></tr><tr><td>WAF-ORA-OE-05</td><td>No update installation has failed on an Oracle VM</td><td>✅ Oracle-image VM → failed patch installation</td><td>REF</td></tr><tr><td>WAF-ORA-OE-06</td><td>Database patching and maintenance are automated and scheduled</td><td>❌ Manual</td><td>REF</td></tr><tr><td>WAF-ORA-OE-07</td><td>Infrastructure and database configuration are deployed as code</td><td>❌ Manual</td><td>OV</td></tr><tr><td>WAF-ORA-OE-08</td><td>File systems mount managed disks by device UUID, not device name</td><td>❌ Manual</td><td>REF</td></tr></tbody></table><h3 id="performance-efficiency-waf-ora-pe-—-8-items" tabindex="-1">Performance efficiency (WAF-ORA-PE) — 8 items <a class="header-anchor" href="#performance-efficiency-waf-ora-pe-—-8-items" aria-label="Permalink to &quot;Performance efficiency (WAF-ORA-PE) — 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-ORA-PE-01</td><td>Oracle VMs have no Standard HDD or Standard SSD data disks</td><td>✅ <code>dataDisks[].managedDisk.storageAccountType</code></td><td>PERF, DES</td></tr><tr><td>WAF-ORA-PE-02</td><td>Oracle VMs boot from a Premium SSD operating-system disk</td><td>✅ <code>osDisk.managedDisk.storageAccountType</code></td><td>DES</td></tr><tr><td>WAF-ORA-PE-03</td><td>No Oracle data disk uses read-write host caching</td><td>✅ <code>dataDisks[].caching</code></td><td>DES</td></tr><tr><td>WAF-ORA-PE-04</td><td>Accelerated networking is enabled on every network interface of every Oracle VM</td><td>✅ Oracle-image VM → network interface with it off</td><td>DES</td></tr><tr><td>WAF-ORA-PE-05</td><td>VM series is memory optimised with a memory-to-vCore ratio suited to Oracle</td><td>❌ Manual — Oracle-image VMs attached</td><td>PERF</td></tr><tr><td>WAF-ORA-PE-06</td><td>Redo, temp and undo are on separate disks; Write Accelerator or Ultra Disk for redo</td><td>❌ Manual</td><td>DES</td></tr><tr><td>WAF-ORA-PE-07</td><td>Disk performance was load-tested and sized by IOPS, not capacity</td><td>❌ Manual</td><td>DES</td></tr><tr><td>WAF-ORA-PE-08</td><td>Guest and placement tuning follows the Oracle on Azure guidance</td><td>❌ Manual</td><td>DES, REF</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pillar</th><th>Items</th><th>Automated (✅)</th><th>Manual (❌)</th></tr></thead><tbody><tr><td>Reliability</td><td>6</td><td>1</td><td>5</td></tr><tr><td>Security</td><td>7</td><td>3</td><td>4</td></tr><tr><td>Cost optimization</td><td>5</td><td>0</td><td>5</td></tr><tr><td>Operational excellence</td><td>8</td><td>1</td><td>7</td></tr><tr><td>Performance efficiency</td><td>8</td><td>4</td><td>4</td></tr><tr><td><strong>Total</strong></td><td><strong>34</strong></td><td><strong>9</strong></td><td><strong>25</strong></td></tr></tbody></table><h2 id="what-is-not-covered" tabindex="-1">What is not covered <a class="header-anchor" href="#what-is-not-covered" aria-label="Permalink to &quot;What is not covered&quot;">​</a></h2><ul><li><strong>Oracle Database@Azure</strong> (<code>oracle.database/*</code>) — see above.</li><li><strong>Oracle on VMs built from non-Oracle images</strong> — invisible to the automated items (see above).</li><li><strong>Oracle RAC</strong> is not supported on Azure; the review treats Data Guard or GoldenGate as the high-availability mechanism.</li><li><strong>Disk-to-VM scoping</strong> is read from the VM&#39;s own <code>storageProfile</code>, so a data disk attached to an Oracle-image VM is scored even if the VM is a non-database server. Disks themselves are not joined (the managed-disk projection carries no <code>managedBy</code>).</li><li>Several automated items read <strong>estate-wide</strong> data (Defender plans) and flag a subscription, not only the Oracle machines in it; the rule text says so.</li></ul>',28)])])}const f=e(d,[["render",s]]);export{m as __pageData,f as default};
